-- ============================================================
-- BỔ SUNG 50 HỌC SINH VÀ PHÂN VÀO KHÓA HỌC AI Programming With Python
-- Mật khẩu mặc định: 123456 (đã hash BCrypt rounds=12)
-- ============================================================

ON CONFLICT (email) DO UPDATE 
SET password_hash = EXCLUDED.password_hash,
    full_name = EXCLUDED.full_name;

-- Phân 50 học sinh vào khóa học AI Programming
SELECT u.id, c.id, 0.00, 'in_progress', CURRENT_TIMESTAMP
FROM users u
CROSS JOIN (
    SELECT id FROM courses WHERE title ILIKE '%AI Programming%' OR id = 11 ORDER BY id DESC LIMIT 1
) c
WHERE u.email LIKE 'student%@lms.com'
ON CONFLICT (student_id, course_id) DO NOTHING;
